+function validateManifest(manifest) {
+  if (!isPlainObject(manifest)) throw Error('manifest must be an object');
+  if (manifest.version !== 1) throw Error('manifest version must be 1');
+  if (!Array.isArray(manifest.files)) throw Error('manifest files must be an array');
+  const seen = new Set();
+  for (const entry of manifest.files) {
+    if (!isPlainObject(entry)) throw Error('manifest entry must be an object');
+    validatePath(entry.path);
+    if (seen.has(entry.path)) throw Error('duplicate manifest path');
+    seen.add(entry.path);
+    if (typeof entry.sha256 !== 'string' || !HEX64.test(entry.sha256)) throw Error('invalid manifest sha256');
+    if (!Number.isSafeInteger(entry.size) || entry.size < 0) throw Error('invalid manifest size');
+    if (!Number.isInteger(entry.mode) || entry.mode < 0 || entry.mode > 0o777) throw Error('invalid manifest mode');
+  }
+}
+export function verifyManifest(root, manifest) {
+  validateRoot(root);
+  validateManifest(manifest);
+  const report = {ok:true,unchanged:[],changed:[],missing:[],unsafe:[]};
+  const entries = [...manifest.files].sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
+  for (const entry of entries) {
+    const current = inspect(root, entry.path);
+    if (current.kind === 'missing') { report.missing.push(entry.path); continue; }
+    if (current.kind === 'unsafe') { report.unsafe.push(entry.path); continue; }
+    const reasons = [];
+    if (current.sha256 !== entry.sha256 || current.size !== entry.size) reasons.push('content');
+    if (current.mode !== entry.mode) reasons.push('mode');
+    if (reasons.length) report.changed.push({path:entry.path,reasons});
+    else report.unchanged.push(entry.path);
+  }
+  report.ok = !report.changed.length && !report.missing.length && !report.unsafe.length;
+  return report;
+}
+function usage() {
+  throw Error('usage: node snapshot.js create ROOT [PATH ...] | node snapshot.js verify ROOT MANIFEST_FILE');
+}
+export function main(argv) {
+  const [command, root, ...rest] = argv;
+  if (command === 'create') {
+    if (root === undefined) usage();
+    return {code:0,output:createManifest(root, rest)};
+  }
+  if (command === 'verify') {
+    if (root === undefined || rest.length !== 1) usage();
+    const manifest = JSON.parse(fs.readFileSync(rest[0], 'utf8'));
+    const report = verifyManifest(root, manifest);
+    return {code:report.ok ? 0 : 1,output:report};
+  }
+  usage();
+}
+function isMainModule() {
+  if (!process.argv[1]) return false;
+  const self = fileURLToPath(import.meta.url);
+  const entry = path.resolve(process.argv[1]);
+  if (entry === self) return true;
+  try { return fs.realpathSync(entry) === fs.realpathSync(self); } catch { return false; }
+}
+if (isMainModule()) {
+  try {
+    const {code, output} = main(process.argv.slice(2));
+    process.stdout.write(JSON.stringify(output) + '\n');
+    process.exitCode = code;
+  } catch (error) {
+    process.stderr.write(`snapshot: ${error && error.message ? error.message : String(error)}\n`);
+    process.exitCode = 2;
+  }
