import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import * as snapshot from '../snapshot.js';
const SCRIPT = fileURLToPath(new URL('../snapshot.js', import.meta.url));
function fixture(t) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(),'snapshot-verify-'));
  fs.mkdirSync(path.join(dir,'sub'));
  fs.writeFileSync(path.join(dir,'a.txt'),'abc'); fs.chmodSync(path.join(dir,'a.txt'),0o640);
  fs.writeFileSync(path.join(dir,'sub','b c.txt'),'hello'); fs.chmodSync(path.join(dir,'sub','b c.txt'),0o600);
  t.after(() => fs.rmSync(dir,{recursive:true,force:true})); return dir;
}
function run(args) { return spawnSync(process.execPath,[SCRIPT,...args],{encoding:'utf8'}); }

test('verify classifies mode, unsafe symlink, and non-directory intermediate', t => {
  const root = fixture(t);
  const manifest = snapshot.createManifest(root,['sub/b c.txt','a.txt']);
  assert.deepEqual(manifest.files.map(f => f.path),['a.txt','sub/b c.txt']);
  fs.chmodSync(path.join(root,'a.txt'),0o600);
  fs.writeFileSync(path.join(root,'sub','b c.txt'),'HELLO'); fs.chmodSync(path.join(root,'sub','b c.txt'),0o644);
  const report = snapshot.verifyManifest(root,manifest);
  assert.deepEqual(report,{ok:false,unchanged:[],changed:[{path:'a.txt',reasons:['mode']},{path:'sub/b c.txt',reasons:['content','mode']}],missing:[],unsafe:[]});
  fs.unlinkSync(path.join(root,'a.txt')); fs.symlinkSync(path.join(root,'sub','b c.txt'),path.join(root,'a.txt'));
  fs.rmSync(path.join(root,'sub'),{recursive:true}); fs.writeFileSync(path.join(root,'sub'),'file');
  assert.deepEqual(snapshot.verifyManifest(root,manifest).unsafe,['a.txt','sub/b c.txt']);
  assert.throws(() => snapshot.createManifest(root,['a.txt']));
});
test('verify does not mutate input and tolerates unsorted entries and unknown fields', t => {
  const root = fixture(t);
  const manifest = snapshot.createManifest(root,['sub/b c.txt','a.txt']);
  const unsorted = {version:1,files:[...manifest.files].reverse().map(f => ({...f,extra:1})),note:'x'};
  const copy = JSON.stringify(unsorted);
  const report = snapshot.verifyManifest(root,unsorted);
  assert.deepEqual(report.unchanged,['a.txt','sub/b c.txt']);
  assert.equal(JSON.stringify(unsorted),copy);
  assert.deepEqual(snapshot.verifyManifest(root,{version:1,files:[]}),{ok:true,unchanged:[],changed:[],missing:[],unsafe:[]});
});
test('invalid manifests and roots throw', t => {
  const root = fixture(t);
  const good = snapshot.createManifest(root,['a.txt']).files[0];
  const bad = [null,[],{version:'1',files:[]},{version:1,files:{}},{version:1,files:[null]},{version:1,files:[[]]},
    {version:1,files:[{...good,sha256:good.sha256.toUpperCase()}]},{version:1,files:[{...good,size:-1}]},
    {version:1,files:[{...good,size:1.5}]},{version:1,files:[{...good,mode:512}]},{version:1,files:[{...good,path:'./a.txt'}]},
    {version:1,files:[good,{...good}]}];
  for (const m of bad) assert.throws(() => snapshot.verifyManifest(root,m), `expected throw for ${JSON.stringify(m)}`);
  assert.throws(() => snapshot.verifyManifest(path.join(root,'nope'),{version:1,files:[]}));
  fs.symlinkSync(root,path.join(root,'link'));
  assert.throws(() => snapshot.verifyManifest(path.join(root,'link'),{version:1,files:[]}));
});
test('CLI create and verify exit codes and streams', t => {
  const root = fixture(t);
  const created = run(['create',root,'a.txt','sub/b c.txt']);
  assert.equal(created.status,0); assert.equal(created.stderr,'');
  assert.deepEqual(JSON.parse(created.stdout),snapshot.createManifest(root,['a.txt','sub/b c.txt']));
  assert.ok(created.stdout.endsWith('\n'));
  const manifestFile = path.join(root,'m.json'); fs.writeFileSync(manifestFile,created.stdout);
  let verified = run(['verify',root,manifestFile]);
  assert.equal(verified.status,0); assert.equal(verified.stderr,''); assert.equal(JSON.parse(verified.stdout).ok,true);
  fs.writeFileSync(path.join(root,'a.txt'),'zzz');
  verified = run(['verify',root,manifestFile]);
  assert.equal(verified.status,1); assert.equal(verified.stderr,''); assert.equal(JSON.parse(verified.stdout).ok,false);
  for (const args of [[],['bogus'],['create'],['verify',root],['verify',root,path.join(root,'none.json')],['create',root,'../x'],['create',path.join(root,'none')]]) {
    const r = run(args); assert.equal(r.status,2,JSON.stringify(args)); assert.equal(r.stdout,''); assert.notEqual(r.stderr,'');
  }
  fs.writeFileSync(manifestFile,'{not json');
  const r = run(['verify',root,manifestFile]); assert.equal(r.status,2); assert.equal(r.stdout,'');
  const empty = run(['create',root]); assert.equal(empty.status,0); assert.deepEqual(JSON.parse(empty.stdout),{version:1,files:[]});
});

